// Package vectorstore 定義向量資料庫抽象與內嵌式 chromem-go 實作。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose service 只依賴 Store 介面，日後可無痛換成 pgvector / Qdrant
package vectorstore

import "context"

// Doc 為待寫入的文件；Metadata 為查詢時可精確過濾的鍵值。
type Doc struct {
	ID       string
	Content  string
	Metadata map[string]string
}

// Hit 為一筆查詢結果；Score 為 cosine 相似度（-1 ~ 1，越大越相近）。
type Hit struct {
	ID       string
	Content  string
	Metadata map[string]string
	Score    float32
}

// Store 為向量資料庫最小介面。
type Store interface {
	// Upsert 寫入文件；同 ID 覆寫。concurrency 控制同時向量化的筆數。
	Upsert(ctx context.Context, docs []Doc, concurrency int) error
	// Query 以 text 向量化後取最相近的 k 筆；where 為 metadata 精確過濾（全部鍵需相符）。
	Query(ctx context.Context, text string, k int, where map[string]string) ([]Hit, error)
	// Count 回傳文件數。
	Count() int
	// Reset 清空集合。
	Reset(ctx context.Context) error
	// Describe 回傳集合 metadata（如建立索引時的 embedding 描述）。
	Describe() map[string]string
}
